/**
 * @name Path traversal in file operations
 * @description User-controlled file paths in S3 transfer operations could allow writing files outside intended directories
 * @kind path-problem
 * @problem.severity error
 * @id py/s3transfer-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters that could contain S3 keys or filenames
    exists(DataFlow::ParameterNode param |
      source = param and
      (
        param.getParameter().getName() in ["key", "filename", "fileobj", "bucket", "extra_args", "s3_key", "dest", "source"]
      )
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File operations that could be vulnerable to path traversal
    exists(DataFlow::CallCfgNode call |
      sink = call.getArg(_) and
      (
        call = API::builtin("open").getACall() or
        call = API::moduleImport("os").getMember(["open", "makedirs", "mkdir", "remove", "unlink", "rename"]).getACall() or
        call = API::moduleImport("os").getMember("path").getMember("join").getACall() or
        call = API::moduleImport("shutil").getMember(["copy", "copy2", "copyfile", "move"]).getACall()
      )
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user-controlled input"

/**
 * @name Sensitive information in logs
 * @description Logging sensitive information can lead to information disclosure
 * @kind path-problem
 * @problem.severity warning
 * @id py/sensitive-info-logging
 * @tags security
 *        external/cwe/cwe-532
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SensitiveLoggingConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::AttrRead attr |
      attr.getAttributeName() in ["password", "secret", "token", "key", "credential", "auth"] and
      source = attr
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("logging").getMember(["debug", "info", "warning", "error", "critical"]).getACall() and
      sink = call.getArg(_)
    )
  }
}

module SensitiveLoggingFlow = TaintTracking::Global<SensitiveLoggingConfig>;
import SensitiveLoggingFlow::PathGraph

from SensitiveLoggingFlow::PathNode source, SensitiveLoggingFlow::PathNode sink
where SensitiveLoggingFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Sensitive information from $@ may be logged.", source.getNode(), "sensitive source"

/**
 * @name SQL injection
 * @description Executing SQL queries with unsanitized user input can lead to SQL injection
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SqlExecution sql |
      sink = sql.getSql()
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL injection from $@.", source.getNode(), "user input"
